# main.py\n\n"""\nFinancial Goal Tracker CLI\n\nFeatures:\n- Load transactions from a CSV (date, amount, category)\n- Define a savings goal (target amount and deadline)\n- Compute current saved amount, remaining amount, and required daily saving rate\n- Export a concise markdown report\n\nUsage:\n  python main.py --transactions transactions.csv \\\n               --goal 5000 --deadline 2026-12-31 [--output report.md]\n\nThe tool uses only the Python standard library and runs on any CPU‑only Windows machine.\n"""\n\nimport argparse, csv, datetime, sys, pathlib\nfrom dataclasses import dataclass, field\nfrom typing import List, Dict\n\n@dataclass\nclass Transaction:\n    date: datetime.date\n    amount: float  # positive for income, negative for expense\n    category: str\n\n    @staticmethod\n    def from_dict(row: Dict[str, str]) -> 'Transaction':\n        try:\n            date = datetime.datetime.strptime(row['date'], '%Y-%m-%d').date()\n        except Exception as e:\n            raise ValueError(f"Invalid date '{row.get('date')}'") from e\n        try:\n            amount = float(row['amount'])\n        except Exception as e:\n            raise ValueError(f"Invalid amount '{row.get('amount')}'") from e\n        category = row.get('category', '').strip() or 'uncategorized'\n        return Transaction(date, amount, category)\n\n@dataclass\nclass Goal:\n    target: float\n    deadline: datetime.date\n\n    @property\n    def days_remaining(self) -> int:\n        delta = (self.deadline - datetime.date.today()).days\n        return max(delta, 0)\n\ndef load_transactions(path: pathlib.Path) -> List[Transaction]:\n    if not path.is_file():\n        sys.exit(f'Error: file not found {path}')\n    with path.open(newline='') as f:\n        reader = csv.DictReader(f)\n        return [Transaction.from_dict(row) for row in reader]\n\ndef compute_savings(transactions: List[Transaction]) -> float:\n    # Sum of positive amounts (income) minus negative amounts (expenses)\n    return sum(t.amount for t in transactions)\n\ndef generate_report(goal: Goal, saved: float) -> str:\n    remaining = max(goal.target - saved, 0)\n    daily_needed = remaining / goal.days_remaining if goal.days_remaining else float('inf')\n    report = [\n        f"# Financial Goal Report",\n        f"**Target:** ${goal.target:,.2f}",\n        f"**Deadline:** {goal.deadline.isoformat()}",\n        f"**Days Remaining:** {goal.days_remaining}",\n        f"---",\n        f"**Saved So Far:** ${saved:,.2f}",\n        f"**Remaining:** ${remaining:,.2f}",\n        f"**Required Daily Saving:** ${daily_needed:,.2f}" if goal.days_remaining else "**Deadline passed**",\n        f"---",\n        f"_Generated on {datetime.date.today().isoformat()}_"\n    ]\n    return "\n\n".join(report)\n\ndef main() -> None:\n    parser = argparse.ArgumentParser(description='Financial Goal Tracker CLI')\n    parser.add_argument('--transactions', type=pathlib.Path, required=True, help='Path to CSV file with columns: date, amount, category')\n    parser.add_argument('--goal', type=float, required=True, help='Target savings amount in dollars')\n    parser.add_argument('--deadline', type=lambda d: datetime.datetime.strptime(d, '%Y-%m-%d').date(), required=True, help='Goal deadline (YYYY-MM-DD)')\n    parser.add_argument('--output', type=pathlib.Path, help='Path to write markdown report (default: stdout)')\n    args = parser.parse_args()\n\n    transactions = load_transactions(args.transactions)\n    saved = compute_savings(transactions)\n    goal = Goal(target=args.goal, deadline=args.deadline)\n    report = generate_report(goal, saved)\n\n    if args.output:\n        args.output.write_text(report, encoding='utf-8')\n        print(f'Report written to {args.output}')\n    else:\n        print(report)\n\nif __name__ == '__main__':\n    main()\n
